INSERT INTO public.projects (slug,title,tag,intro,summary,image_url,image_alt,technologies,external_url,featured,sort_order,status,content) VALUES ('cluster-haute-disponibilite','Infrastructure haute disponibilité par cluster étendu','Projet de fin d''études','Ce projet de fin d''études porte sur la continuité des services informatiques. Le principe d''un cluster étendu est de répartir les ressources sur plusieurs sites pour ne pas dépendre d''un seul serveur ou d''un seul emplacement.','Une panne de serveur peut interrompre tous les services d''une organisation pendant des heures.','/__l5e/assets-v1/6a04d474-3cfe-4cdc-86a3-b584cc28b128/p-servers.jpg','Tableau de bord de supervision de serveurs sur un ordinateur portable',ARRAY['Cluster','Linux','Virtualisation','Haute disponibilité']::text[],NULL,true,0,'published','[{"id": "bb80c8fefa6", "type": "heading", "text": "Le besoin de départ", "layout": "half"}, {"id": "b334b6b3112", "type": "paragraph", "doc": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Une panne de serveur peut interrompre tous les services d''une organisation pendant des heures."}]}]}}, {"id": "bc093c7f66e", "type": "heading", "text": "Mon rôle", "layout": "half"}, {"id": "bff6c5a08b2", "type": "paragraph", "doc": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Conception et déploiement d''un cluster étendu sur plusieurs sites, avec bascule automatique des services."}]}]}}, {"id": "bafca48e959", "type": "heading", "text": "La démarche", "tone": "muted", "variant": "steps"}, {"id": "bc6577abe8c", "type": "subheading", "text": "Répartir les services"}, {"id": "b5bd2086634", "type": "paragraph", "doc": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "La conception s''appuie sur plusieurs nœuds et plusieurs sites pour limiter les points de défaillance uniques."}]}]}}, {"id": "bc06243dcea", "type": "subheading", "text": "Prévoir la bascule"}, {"id": "bb756dcb036", "type": "paragraph", "doc": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "La bascule automatique permet à un autre nœud de prendre le relais lorsque le service principal devient indisponible."}]}]}}, {"id": "be1e5b788f4", "type": "subheading", "text": "Assurer la continuité"}, {"id": "b2342aa206c", "type": "paragraph", "doc": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Linux et la virtualisation sont utilisés dans une infrastructure orientée haute disponibilité."}]}]}}, {"id": "b3a8b9d4cb2", "type": "heading", "text": "Le projet en images"}, {"id": "b12f1810436", "type": "image", "url": "/__l5e/assets-v1/40da67c3-cdf2-4e57-84ed-ae35bc7e9ff5/cap-cluster.jpg", "alt": "Schéma illustratif de serveurs répartis sur deux sites", "title": "Comprendre le cluster étendu", "caption": "Les deux sites représentent le principe de répartition des ressources. Les flèches illustrent la réplication et le relais entre les nœuds, sans reproduire la configuration exacte du projet.", "note": "Illustration explicative — les captures réelles du projet seront ajoutées lorsqu''elles seront disponibles."}, {"id": "bfc340caed6", "type": "heading", "text": "Résultat", "variant": "result"}, {"id": "b6d5f64e6d5", "type": "paragraph", "doc": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Les services restent accessibles même si un nœud ou un site tombe en panne."}]}]}}]'::jsonb);
INSERT INTO public.projects (slug,title,tag,intro,summary,image_url,image_alt,technologies,external_url,featured,sort_order,status,content) VALUES ('paylix','PayLix — gestion des frais scolaires','En cours de développement','PayLix est une plateforme en cours de développement pour la gestion des frais scolaires. Elle vise à remplacer un suivi dispersé sur papier par une vue structurée des paiements, au service des écoles, des parents et de l''administration.','Les écoles publiques et privées suivent encore souvent les paiements sur papier, avec erreurs et retards.','/__l5e/assets-v1/270ac3f0-fe37-4427-b3dc-a38f18c4309f/p-web.jpg','Application web affichée sur un ordinateur et un smartphone',ARRAY['Développement web','Base de données','Tableaux de bord']::text[],'https://paylix-gamma.vercel.app/',true,1,'published','[{"id": "b7fb92d7386", "type": "heading", "text": "Le besoin de départ", "layout": "half"}, {"id": "b071beeb1b1", "type": "paragraph", "doc": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Les écoles publiques et privées suivent encore souvent les paiements sur papier, avec erreurs et retards."}]}]}}, {"id": "b70ede393d2", "type": "heading", "text": "Mon rôle", "layout": "half"}, {"id": "b38a01d76c5", "type": "paragraph", "doc": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Conception et développement complet de la plateforme, de la base de données à l''interface."}]}]}}, {"id": "b289dd7fb89", "type": "heading", "text": "La démarche", "tone": "muted", "variant": "steps"}, {"id": "b2c6e5af15b", "type": "subheading", "text": "Structurer les informations"}, {"id": "b51e4ac9a92", "type": "paragraph", "doc": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "La base de données constitue le socle de la plateforme : elle permet d''organiser les informations nécessaires au suivi des frais scolaires."}]}]}}, {"id": "bb515d77a16", "type": "subheading", "text": "Rendre le suivi lisible"}, {"id": "b1fdaa47a21", "type": "paragraph", "doc": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "L''interface et les tableaux de bord visent à rendre les paiements plus faciles à consulter et à comprendre."}]}]}}, {"id": "b163990cd9f", "type": "subheading", "text": "Développer la plateforme"}, {"id": "b0c49e57f9f", "type": "paragraph", "doc": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Je prends en charge la conception et le développement, de la base de données jusqu''à l''interface. Le projet est encore en cours : le résultat présenté est son objectif."}]}]}}, {"id": "bfb5ee05b8f", "type": "heading", "text": "Le projet en images"}, {"id": "bab827ed286", "type": "image", "url": "/__l5e/assets-v1/05b0d965-f13e-429c-8856-ac2e4d02d558/cap-paylix.jpg", "alt": "Maquette illustrative d''un tableau de bord de frais scolaires", "title": "Une vue d''ensemble des paiements", "caption": "Cet exemple montre comment une liste d''élèves, des statuts de paiement et une synthèse peuvent faciliter le suivi. Les noms et chiffres sont fictifs ; il ne s''agit pas d''une capture réelle de PayLix.", "note": "Illustration explicative — les captures réelles du projet seront ajoutées lorsqu''elles seront disponibles."}, {"id": "b31c1fa4986", "type": "heading", "text": "Objectif du projet en cours", "variant": "result"}, {"id": "b80798e7040", "type": "paragraph", "doc": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Un suivi clair des paiements pour les écoles, les parents et l''administration."}]}]}}]'::jsonb);
INSERT INTO public.projects (slug,title,tag,intro,summary,image_url,image_alt,technologies,external_url,featured,sort_order,status,content) VALUES ('marketnet','MarketNet — boutiques en ligne avec commandes sur WhatsApp','Projet personnel','Une plateforme où le commerçant crée sa boutique en quelques minutes depuis son smartphone et reçoit des commandes structurées sur WhatsApp.','De nombreux commerçants de RDC et d''Afrique francophone vendent via leurs statuts WhatsApp et doivent répéter les prix en message privé, envoyer des dizaines de photos et gérer des commandes floues (taille, couleur, adresse).','/__l5e/assets-v1/771406a1-f39a-4601-9a34-3edbf9fc5d2f/p-marketnet.jpg','Maquette d''un smartphone affichant une boutique en ligne',ARRAY['Développement web','Authentification','Intégration WhatsApp','Mobile-first']::text[],'https://appmarketnet.vercel.app/',true,2,'published','[{"id": "bdcf7bebe2a", "type": "heading", "text": "Le besoin de départ", "layout": "half"}, {"id": "be21fe6d462", "type": "paragraph", "doc": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "De nombreux commerçants de RDC et d''Afrique francophone vendent via leurs statuts WhatsApp et doivent répéter les prix en message privé, envoyer des dizaines de photos et gérer des commandes floues (taille, couleur, adresse)."}]}]}}, {"id": "b7c6a3a8ecf", "type": "heading", "text": "Mon rôle", "layout": "half"}, {"id": "bc64e6ce645", "type": "paragraph", "doc": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Conception et développement de la plateforme."}]}]}}, {"id": "b3577af1c29", "type": "heading", "text": "Solution", "layout": "half", "tone": "muted"}, {"id": "bbf2f7049cd", "type": "paragraph", "doc": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Une plateforme où le commerçant crée sa boutique en quelques minutes depuis son smartphone. Il partage un lien unique (statut WhatsApp, TikTok, Instagram, Facebook). Le client parcourt le catalogue sans rien installer, choisit les options (tailles, couleurs, quantités), et la commande arrive pré-remplie et structurée sur WhatsApp, avec le total."}]}]}}, {"id": "b760d67d4fb", "type": "heading", "text": "Fonctionnalités", "layout": "half", "tone": "muted"}, {"id": "b33921e5421", "type": "list", "style": "check", "doc": {"type": "doc", "content": [{"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Prix affichés en dollars ($) et en francs congolais (FC) selon le taux du vendeur"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Variantes de produits"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Personnalisation de la boutique (couleurs, bannière, catégories)"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Vitrine légère pensée pour mobile et connexions lentes"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Inscription et connexion pour les commerçants"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "0 % de commission annoncé sur la plateforme"}]}]}]}]}}, {"id": "bdea2dfca19", "type": "heading", "text": "Technologies & outils"}, {"id": "b4ffb1b168d", "type": "list", "style": "tags", "doc": {"type": "doc", "content": [{"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Développement web"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Authentification"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Intégration WhatsApp"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Mobile-first"}]}]}]}]}}, {"id": "bc3eb1b7d70", "type": "button", "label": "Accéder au site", "url": "https://appmarketnet.vercel.app/"}, {"id": "b5c2b23de4b", "type": "heading", "text": "Le projet en images"}, {"id": "bbf8d3ce767", "type": "image", "url": "/__l5e/assets-v1/771406a1-f39a-4601-9a34-3edbf9fc5d2f/p-marketnet.jpg", "alt": "Maquette illustrative d''un smartphone affichant une boutique en ligne", "title": "Une boutique en ligne sur smartphone", "caption": "Image provisoire : maquette générale d''une boutique sur smartphone. Elle sera remplacée par de vraies captures d''écran de MarketNet.", "note": "Illustration explicative — les captures réelles du projet seront ajoutées lorsqu''elles seront disponibles."}]'::jsonb);
INSERT INTO public.projects (slug,title,tag,intro,summary,image_url,image_alt,technologies,external_url,featured,sort_order,status,content) VALUES ('reseaux-pme','Mise en place de réseaux pour PME','XSECURITY','Au sein de XSECURITY, je participe à la mise en place de réseaux pour de petites entreprises. L''objectif est de permettre aux équipes de travailler avec une connexion stable et de partager leurs ressources sur un réseau organisé.','De petites entreprises avaient besoin d''un réseau stable pour travailler et partager leurs ressources.','/__l5e/assets-v1/68c611d2-498f-4c7c-b4e9-720169a9a283/p-network.jpg','Baie de brassage avec câbles réseau bleus organisés',ARRAY['LAN','Câblage','Équipements Cisco','Wi-Fi']::text[],NULL,true,3,'published','[{"id": "bcfff2af7ed", "type": "heading", "text": "Le besoin de départ", "layout": "half"}, {"id": "b3fb5eb5f71", "type": "paragraph", "doc": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "De petites entreprises avaient besoin d''un réseau stable pour travailler et partager leurs ressources."}]}]}}, {"id": "b3d04c8a6cc", "type": "heading", "text": "Mon rôle", "layout": "half"}, {"id": "b3d930c8ba9", "type": "paragraph", "doc": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Installation, câblage, configuration des équipements et dépannage en équipe."}]}]}}, {"id": "b2018fde119", "type": "heading", "text": "La démarche", "tone": "muted", "variant": "steps"}, {"id": "be2ca90333f", "type": "subheading", "text": "Installer et câbler"}, {"id": "b1191d1bc0d", "type": "paragraph", "doc": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "L''installation physique et le câblage relient les postes et les équipements pour constituer le réseau local."}]}]}}, {"id": "b0216aff85c", "type": "subheading", "text": "Configurer les équipements"}, {"id": "bfc13841d8e", "type": "paragraph", "doc": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "La configuration des équipements réseau et du Wi-Fi permet aux utilisateurs d''accéder aux ressources nécessaires à leur travail."}]}]}}, {"id": "beba453cadb", "type": "subheading", "text": "Dépanner et documenter"}, {"id": "ba684506584", "type": "paragraph", "doc": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Le dépannage s''effectue en équipe. Une organisation claire et une documentation du réseau facilitent son suivi."}]}]}}, {"id": "b7f8da4f92a", "type": "heading", "text": "Le projet en images"}, {"id": "b6c2adc8791", "type": "image", "url": "/__l5e/assets-v1/a639f3e5-c523-4ac6-99d7-6871d7f9a9c7/cap-lan.jpg", "alt": "Schéma illustratif d''un réseau local avec postes, commutateur et Wi-Fi", "title": "Les éléments d''un réseau d''entreprise", "caption": "Ce schéma présente les connexions possibles entre Internet, les équipements réseau, les postes et les ressources partagées. C''est une illustration générale, et non le plan d''un réseau client.", "note": "Illustration explicative — les captures réelles du projet seront ajoutées lorsqu''elles seront disponibles."}, {"id": "b6aa2703bd2", "type": "heading", "text": "Résultat", "variant": "result"}, {"id": "b5bccf91eae", "type": "paragraph", "doc": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Des réseaux fonctionnels, organisés et documentés pour nos clients."}]}]}}]'::jsonb);
INSERT INTO public.projects (slug,title,tag,intro,summary,image_url,image_alt,technologies,external_url,featured,sort_order,status,content) VALUES ('securisation-systemes','Sécurisation des systèmes clients','XSECURITY','Cette activité menée au sein de XSECURITY concerne la protection des postes et des données d''entreprise. Elle associe les règles d''accès, les protections des systèmes et les sauvegardes pour réduire l''exposition aux risques.','Des postes et données d''entreprise étaient exposés faute de règles de sécurité claires.','/__l5e/assets-v1/5f754ad5-487d-4051-915d-506aeb6c7324/p-security.jpg','Pare-feu réseau avec un cadenas lumineux symbolisant la sécurité',ARRAY['Pare-feu','Contrôle d''accès','Sauvegardes']::text[],NULL,false,4,'published','[{"id": "b88d39dc93c", "type": "heading", "text": "Le besoin de départ", "layout": "half"}, {"id": "b6f172386e9", "type": "paragraph", "doc": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Des postes et données d''entreprise étaient exposés faute de règles de sécurité claires."}]}]}}, {"id": "b4905e95eda", "type": "heading", "text": "Mon rôle", "layout": "half"}, {"id": "b76ec6198b8", "type": "paragraph", "doc": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Mise en place de règles d''accès, de protections et de sauvegardes."}]}]}}, {"id": "bf6d5d99ecf", "type": "heading", "text": "La démarche", "tone": "muted", "variant": "steps"}, {"id": "bc9e8e7114c", "type": "subheading", "text": "Encadrer les accès"}, {"id": "b1fd49624f6", "type": "paragraph", "doc": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Les règles d''accès définissent quelles ressources peuvent être utilisées et permettent de limiter les accès non souhaités."}]}]}}, {"id": "bc02033195e", "type": "subheading", "text": "Renforcer les protections"}, {"id": "b9a600b23bb", "type": "paragraph", "doc": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Les protections et le pare-feu contribuent à réduire l''exposition des systèmes clients."}]}]}}, {"id": "b71d3d7474c", "type": "subheading", "text": "Préserver les données"}, {"id": "b5a58e2355d", "type": "paragraph", "doc": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Les sauvegardes complètent les protections pour mieux préserver les données de l''entreprise."}]}]}}, {"id": "bf834e66447", "type": "heading", "text": "Le projet en images"}, {"id": "b3c7ea849af", "type": "image", "url": "/__l5e/assets-v1/eb98c6f4-3cbd-41f4-b11f-99d17d1e9157/cap-security.jpg", "alt": "Maquette illustrative d''une console de sécurité et de sauvegardes", "title": "Accès, protections et sauvegardes", "caption": "Cet exemple réunit des règles d''accès et un suivi des sauvegardes. Les adresses, règles et statuts affichés sont fictifs et ne correspondent à aucun système client.", "note": "Illustration explicative — les captures réelles du projet seront ajoutées lorsqu''elles seront disponibles."}, {"id": "b1604bfebdd", "type": "heading", "text": "Résultat", "variant": "result"}, {"id": "b898b12809e", "type": "paragraph", "doc": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Des données mieux protégées et des risques réduits pour les clients."}]}]}}]'::jsonb);
